(* [comment removed for export] *)
Definition head (R : bvmap 5 word) (sp c e t : Z) : Prop :=
  getr R (reg 2) = Z_to_bv 64 sp /\ getr R (reg 5) = Z_to_bv 64 t /\ getr R (reg 10) = Z_to_bv 64 c /\ getr R (reg 11) = Z_to_bv 64 e
  /\ getr R (reg 12) = Z_to_bv 64 5 /\ getr R (reg 13) = Z_to_bv 64 10 /\ getr R (reg 14) = Z_to_bv 64 1 /\ getr R (reg 15) = Z_to_bv 64 13
  /\ getr R (reg 16) = Z_to_bv 64 8185 /\ getr R (reg 17) = Z_to_bv 64 80872.

Section Loop.
Variable M : word -> option byte.
Variables (sp p e : Z).
Hypothesis RO : L5.img_clear M 65536 758952.
Hypothesis DEF : L5.defined M p (e - p).
Hypothesis Hsp : 0 <= sp < 2 ^ 64.
Hypothesis Hp : 0 <= p.
Hypothesis He : e <= 2 ^ 47.
Hypothesis Hn : e - p < 2 ^ 26.

