Definition goal_from (fx : FPState) (R : bvmap 5 word) (pc : Z) : Prop :=
  exists fx' R' pc', msteps RSEGS (st fx R pc M) (st fx' R' pc' M) /\ (pc' = 0x39994 \/ pc' = 0x3998c) /\ (forall k, In k KEEP -> getr R' (reg k) = getr R (reg k)).

